function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) {
  if (v === true) return true;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return false;
}
const items = $input.all();
return items.filter(item => {
  const j = item.json || {};
  const publicationRetryAt = Date.parse(safeStr(j.next_retry_at));
  const publicationRetryPending =
    safeStr(j.last_error_stage) === 'publication' &&
    Number.isFinite(publicationRetryAt) &&
    publicationRetryAt > Date.now();
  if (publicationRetryPending) return false;
  if (!safeStr(j.websiteArticle)) return false;
  if (safeBool(j.wordpressGoslarPosted)) return false;
  if (!safeStr(j.vorgangKey)) return false;
  return true;
});

function parseDate(v) { if (!v) return 0; const t = Date.parse(String(v)); return Number.isFinite(t) ? t : 0; }
const items = $input.all();
items.sort((a, b) => parseDate((a.json||{}).firstseen) - parseDate((b.json||{}).firstseen));
return items;

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function esc(v) { return safeStr(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function slugify(v) {
  return safeStr(v).toLowerCase()
    .replace(/[ä]/g,'ae').replace(/[ö]/g,'oe').replace(/[ü]/g,'ue').replace(/[ß]/g,'ss')
    .replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').substring(0,80);
}
const j = $json;
const title = safeStr(j.websiteHeadline) || (safeStr(j.vorgangsnummer) + ' - ' + safeStr(j.title));
const paragraphs = safeStr(j.websiteArticle).split(/\n\s*\n/).filter(Boolean).map(p => '<p>' + esc(p).replace(/\n/g, '<br>') + '</p>').join('\n');
const footer = '<p><em>Vorgangsnummer: ' + esc(j.vorgangsnummer) + ' | <a href="' + esc(j.allrisUrl) + '">Original bei ALLRIS</a></em></p>';
const content = paragraphs + '\n' + footer;
const slug = slugify(safeStr(j.vorgangsnummer) + ' ' + title);
const hasImage = !!safeStr(j.imageFinalPath);
return {
  json: {
    ...j,
    wpTitle: title,
    wpContent: content,
    wpSlug: slug,
    hasImage: hasImage
  }
};

const idx = $itemIndex;
const original = $('Baue Post-Body').itemMatching(idx).json;
const resp = $json || {};
const postId = resp.id || resp.data?.id || null;
const postLink = resp.link || resp.data?.link || '';
const postError = resp.error?.message || resp.error || resp.message || '';
return {
  json: {
    ...original,
    wpPostId: postId,
    wpPostLink: postLink,
    wpPostSuccess: !postError && !!postId,
    wpPostError: postError ? String(postError) : ''
  }
};

const original = $('Baue Post-Body').item.json;
const responses = $input.all().map(item => item.json || {});

function safe(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function isLookupError(j) {
  return Boolean(j.error || j.name === 'NodeApiError' || Number(j.statusCode || j.status || 0) >= 400);
}

const lookupError = responses.find(isLookupError);
const expectedSlug = safe(original.wpSlug);
const existingPost = responses.find(j =>
  !isLookupError(j) && Boolean(j.id) && safe(j.slug) === expectedSlug
);
const lookupErrorMessage = lookupError
  ? (safe(lookupError.error?.message) || safe(lookupError.message) || 'WordPress-Slug-Suche der Partei-Webseite fehlgeschlagen.')
  : '';

return [{
  json: {
    ...original,
    _partySlugExists: Boolean(existingPost),
    _partySlugLookupOk: !lookupError,
    id: existingPost?.id || '',
    link: existingPost?.link || '',
    error: lookupError ? { message: lookupErrorMessage } : undefined
  }
}];

const idx = $itemIndex;
const original = $('Baue Post-Body').itemMatching(idx).json;
const uploadResult = $json;
const mediaId = uploadResult && uploadResult.id ? uploadResult.id : null;
return { json: { ...original, wpFeaturedMediaId: mediaId } };

const now = Date.now();
const owner = `ALLRIS_P8_Partei_Webseite:${$execution.id}`;
return items
  .filter(item => {
    const j = item.json || {};
    const oldOwner = String(j.claim_owner || '').trim();
    const expires = Date.parse(String(j.claim_expires_at || ''));
    return !oldOwner || !Number.isFinite(expires) || expires <= now;
  })
  .map(item => ({ json: {
    ...item.json,
    claimAction: 'acquire',
    claimOwner: owner,
    claimStage: 'publication',
    leaseMinutes: 30,
    expectedClaimOwner: item.json.claim_owner ?? null,
    expectedClaimExpiresAt: item.json.claim_expires_at ?? null
  } }));

const vorgangKey = String($json.vorgangKey || '').trim();
if (!vorgangKey) throw new Error('[P8 Claim Release] vorgangKey fehlt.');
return [{ json: { vorgangKey, claimAction: 'release', claimOwner: `ALLRIS_P8_Partei_Webseite:${$execution.id}` } }];

